package net.civeira.phylax.feature.access.userverificationcode.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ReturnUrlVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property return url of user verification code ")
  void test_return_url_v_o_builder() {
    Assertions.assertFalse(ReturnUrlVO.nullValue().getReturnUrl().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(ReturnUrlVO.tryFrom(null).getReturnUrl().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", ReturnUrlVO.from("one").getReturnUrl().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> ReturnUrlVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", ReturnUrlVO.from("one").toString());
  }
}
